                counts[grid[a][b]] = counts.get(grid[a][b], 0) + 1
                for da, db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na, nb = a+da, b+db
                    if 0 <= na < h and 0 <= nb < w and (na,nb) not in labels and grid[na][nb] not in (bg,line):
                        labels[na,nb] = k
                        stack.append((na,nb))
            colors.append(max(counts, key=counts.get))

    net = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == line}
    def neighbors(p):
        r,c = p
        return [q for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if q in net]

    # Remove all branches, leaving just the cyclic separator skeleton.
    degree = {p: len(neighbors(p)) for p in net}
    queue = [p for p in net if degree[p] < 2]
    peeled = set(queue)
    i = 0
    while i < len(queue):
        p = queue[i]
        i += 1
        for q in neighbors(p):
            if q not in peeled:
                degree[q] -= 1
                if degree[q] < 2:
                    peeled.add(q)
                    queue.append(q)

    # Color a peeled path by nearest object endpoint.  A junction directly
    # adjoining the surviving skeleton remains separator-colored.
    seen = set()
    for start in peeled:
        if start in seen:
            continue
        stack = [start]
        seen.add(start)
        component = []
        while stack:
            p = stack.pop()
            component.append(p)
            for q in neighbors(p):
                if q in peeled and q not in seen:
                    seen.add(q)
                    stack.append(q)
        owner, dist, queue = {}, {}, []
        for p in component:
            r,c = p
            ks = {labels[q] for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if q in labels}
            for k in ks:
                if p not in dist:
                    dist[p] = 0
                    owner[p] = k
                    queue.append(p)
        i = 0
        while i < len(queue):
            p = queue[i]
            i += 1
            for q in neighbors(p):
                if q in peeled and q not in dist:
                    dist[q] = dist[p] + 1
                    owner[q] = owner[p]
                    queue.append(q)
        for p in component:
            if p in owner and all(q in peeled for q in neighbors(p)):
                out[p[0]][p[1]] = colors[owner[p]]
    return out
